UPDATE consultation
SET
    consult_start_date = #{consultStartDate},
    consult_end_date = #{consultEndDate},
    consult_type = #{consultType},
    expert_id = #{expertId},
    contact_phone = #{contactPhone}
WHERE consult_id = #{consultId}
  AND member_id = #{memberId}
  AND status = 1

UPDATE consultation
SET status = 4
WHERE consult_id = #{consultId}
  AND member_id = #{memberId}
  AND status IN (1, 2)

UPDATE consultation
SET status = #{status}
WHERE consult_id = #{consultId}

mapper.select:
SELECT c.consult_id, c.consult_type, c.consult_start_date, c.consult_end_date, c.created_date, c.status, c.contact_phone, u.user_name AS expertName, eu.specialty, iq.content AS consultContent, cn.content AS callNoteContent FROM consultation c JOIN user u ON u.member_id = c.expert_id JOIN expert_user eu ON eu.member_id = c.expert_id
LEFT JOIN ( SELECT i1.consult_id, i1.content FROM inquiry i1 JOIN ( SELECT consult_id, MAX(write_date) AS max_dt FROM inquiry WHERE comment_type = '질문' GROUP BY consult_id ) t ON t.consult_id = i1.consult_id AND t.max_dt = i1.write_date WHERE i1.comment_type = '질문' ) iq ON iq.consult_id = c.consult_id
LEFT JOIN ( SELECT i1.consult_id, i1.content FROM inquiry i1 JOIN ( SELECT consult_id, MAX(write_date) AS max_dt FROM inquiry WHERE comment_type = '전화상담기록' GROUP BY consult_id ) t ON t.consult_id = i1.consult_id AND t.max_dt = i1.write_date WHERE i1.comment_type = '전화상담기록' ) cn ON cn.consult_id = c.consult_id
WHERE c.member_id = #{memberId}
AND u.user_name LIKE CONCAT('%', #{expertName}, '%')
AND c.consult_type = #{consultType}
AND c.status = #{status}
AND DATE(c.consult_start_date) >= #{dateFrom}
AND DATE(c.consult_start_date) <= #{dateTo}
ORDER BY c.consult_start_date DESC, c.consult_id DESC

