SET
    content = #{content},
    write_date = NOW()

        , file_original_name = #{fileOriginalName}
        , file_stored_name = #{fileStoredName}
        , file_path = #{filePath}

WHERE consult_id = #{consultId}
  AND comment_type = '전화상담기록'
